<script lang="ts">import Operation from '$lib/components/workspace/Operation.svelte';let {data}=$props();</script><svelte:head><title>概览 · 站长工作台</title></svelte:head><main><h1>站长工作台</h1><div class="counts"><a href="/workspace/content">未归档内容 {data.counts.total}</a><a href="/workspace/content?published=no">未公开内容 {data.counts.drafts}</a><a href="/workspace/content?published=yes">已公开 {data.counts.published}</a><a href="/workspace/schedules">到期未发 {data.counts.overdue}</a></div><div class="operations"><Operation title="排期扫描" status={data.scanner}/><Operation title="服务器备份" status={data.backups}/><Operation title="Mac 异地副本" status={data.remote}/><Operation title="评论导出" status={data.comments}/><Operation title="存储容量" status={data.storage}/></div><section><h2>最近草稿</h2>{#each data.drafts as draft}<p><a href={`/workspace/content/${draft.id}/edit`}>{draft.title}</a> · {new Date(draft.updated_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}</p>{/each}{#if !data.drafts.length}<p>尚无草稿。</p>{/if}</section><section><h2>排期异常与未来 24 小时</h2>{#each data.upcoming as schedule}<p><a href={`/workspace/schedules/${schedule.id}`}>{schedule.status} · {new Date(schedule.run_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}</a></p>{/each}{#if !data.upcoming.length}<p>暂无需要处理的排期。</p>{/if}</section><section><h2>服务快捷入口</h2>{#each data.services as service}<p><a href={service.url} target="_blank" rel="noopener noreferrer">{service.name} ↗</a> · 人工状态 {service.status} · 更新于 {new Date(service.status_updated_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}</p>{/each}{#if !data.services.length}<a href="/workspace/services">添加服务入口</a>{/if}</section></main><style>.counts,.operations{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:24px;margin-block:24px}.counts a{padding:20px;background:var(--soft);border-radius:12px}</style>
